codeExamples.code:
-- CREATE: define a new table
CREATE TABLE customers (
    customer_id INT PRIMARY KEY,
    customer_name VARCHAR(100) NOT NULL,
    city VARCHAR(50)
);

-- ALTER: change the table's structure
ALTER TABLE customers ADD COLUMN email VARCHAR(255);
ALTER TABLE customers ALTER COLUMN city SET DEFAULT 'Unknown';

-- TRUNCATE: remove all rows quickly (structure kept)
TRUNCATE TABLE customers;

-- DROP: remove the table entirely
DROP TABLE customers;

BEGIN;  -- start a transaction (TCL)

-- DML: move 100 from account 1 to account 2
UPDATE accounts SET balance = balance - 100 WHERE account_id = 1;
UPDATE accounts SET balance = balance + 100 WHERE account_id = 2;

SAVEPOINT after_transfer;  -- TCL: mark a rollback point

-- DML: log the transfer
INSERT INTO transfers (from_acct, to_acct, amount)
VALUES (1, 2, 100);

-- DQL: verify balances before committing
SELECT account_id, balance FROM accounts WHERE account_id IN (1, 2);

COMMIT;  -- TCL: make all changes permanent
-- (or ROLLBACK; to undo everything, or ROLLBACK TO after_transfer;)

-- DCL: allow an analyst role to read orders
GRANT SELECT ON orders TO analyst_role;

-- DCL: allow the app role to read and write
GRANT SELECT, INSERT, UPDATE ON orders TO app_role;

-- DCL: remove write access from a role
REVOKE INSERT, UPDATE ON orders FROM app_role;
